INTENT: {{ $json.intent }}
CONTEXT: {{ $json.context }}
TARGET PATH: {{ $json.target_path }}

Create a structured plan with discrete steps.

Respond ONLY in valid JSON. No markdown fences.

Schema:
{
  "plan_meta": {
    "intent_summary": "one line summary",
    "plan_reasoning": "why this approach"
  },
  "steps": [
    {
      "step_id": "step_1",
      "title": "clear title",
      "description": "what to do",
      "target_file": "filename.ext",
      "expected_output": "what success looks like",
      "reasoning": "why this step matters"
    }
  ]
}

parameters.jsCode:
const data = $input.first().json;
let content = data.response || data.raw || '';
if (content.startsWith('```')) {
  content = content.replace(/^```[\w]*\n?/, '').replace(/```$/, '').trim();
}
let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) { parsed = JSON.parse(jsonMatch[0]); }
  else { parsed = JSON.parse(content); }
} catch(e) { throw new Error('Could not parse planner output: ' + e.message); }
const steps = parsed.steps || [];
return steps.map(step => ({
  json: {
    step: step,
    plan_meta: parsed.plan_meta,
    target_path: $('Parse Input').first().json.target_path,
    model: $('Parse Input').first().json.model,
    intent: $('Parse Input').first().json.intent,
    context: $('Parse Input').first().json.context
  }
}));

