const step = $input.first().json;
const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, -5);
const filename = `${timestamp}-step-${step.step_id}.md`;
const logContent = `---
tags: [director/log, ai-execution]
date: ${now.toISOString()}
step_id: ${step.step_id}
cloud_used: ${step.cloud_used}
---

# Execution Log: ${step.step_title}

## Metadata
- **Run ID**: ${$runId}
- **Timestamp**: ${now.toLocaleString()}
- **Step ID**: ${step.step_id}
- **Target File**: ${step.target_file}
- **Cloud Model**: ${step.cloud_used ? 'Yes' : 'No (Local Ollama)'}

## Plan Context
### Intent Summary
${step.plan_meta.intent_summary}

### Plan Reasoning
${step.plan_meta.plan_reasoning}

## Execution Details
### Approach
${step.reasoning?.approach || 'N/A'}

### Decisions
${step.reasoning?.decisions?.map(d => `- **${d.decision}**\n  - Alternative: ${d.alternative}\n  - Why: ${d.why_chosen}`).join('\n') || 'None recorded'}

### Assumptions
${step.reasoning?.assumptions?.map(a => `- ${a}`).join('\n') || 'None recorded'}

## Notes
${step.notes || 'No additional notes'}

## File Path
Output written to: \`${step.target_path}/${step.target_file}\`
`;
return [{
  json: {
    ...step,
    log_filename: filename,
    log_content: logContent,
    log_path: `D:/ToE/ObsidianVaults/AsherGraves/Director Logs/${filename}`
  }
}];

