const data = $input.first().json;
const content = data.choices?.[0]?.message?.content || '';
let cleaned = content.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/```$/, '').trim();
}
let result;
try {
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) { result = JSON.parse(jsonMatch[0]); }
  else { result = JSON.parse(cleaned); }
} catch(e) {
  throw new Error('Could not parse cloud executor output: ' + e.message + '\n\nRaw: ' + cleaned);
}
return [{
  json: {
    target_file: $json.step.target_file,
    file_content: result.output,
    reasoning: result.reasoning,
    notes: result.notes,
